package com.computerstore.order.controller;
import java.math.BigDecimal; import java.util.*;
import com.computerstore.catalog.repository.ProductRepository; import com.computerstore.common.exception.ResourceNotFoundException; import com.computerstore.inventory.repository.InventoryRepository; import com.computerstore.order.domain.*; import com.computerstore.order.dto.*; import com.computerstore.order.repository.CustomerOrderRepository; import com.computerstore.security.AuthenticatedUser; import com.computerstore.user.repository.UserAccountRepository;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/orders") public class OrderController { private final CustomerOrderRepository orders; private final ProductRepository products; private final InventoryRepository inventory; private final UserAccountRepository users; public OrderController(CustomerOrderRepository orders,ProductRepository products,InventoryRepository inventory,UserAccountRepository users){this.orders=orders;this.products=products;this.inventory=inventory;this.users=users;}
 @PostMapping @Transactional public ResponseEntity<OrderResponse> create(@Valid @RequestBody CreateOrderRequest request,@org.springframework.security.core.annotation.AuthenticationPrincipal AuthenticatedUser auth){var user=users.findById(auth.id()).orElseThrow(()->new ResourceNotFoundException("User not found.")); var items=new ArrayList<OrderItem>(); for(var input:request.items()){var product=products.findById(input.productId()).filter(p->p.isActive()).orElseThrow(()->new ResourceNotFoundException("Product not found."));inventory.findByProductIdForUpdate(product.getId()).orElseThrow(()->new ResourceNotFoundException("Inventory not found.")).reserve(input.quantity());items.add(new OrderItem(product,input.quantity()));} var total=items.stream().map(OrderItem::getSubtotal).reduce(BigDecimal.ZERO,BigDecimal::add);return ResponseEntity.status(HttpStatus.CREATED).body(response(orders.save(new CustomerOrder(user,items,total))));}
 @GetMapping("/me") @Transactional(readOnly=true) public List<OrderResponse> mine(@org.springframework.security.core.annotation.AuthenticationPrincipal AuthenticatedUser auth){return orders.findByUserIdOrderByCreatedAtDesc(auth.id()).stream().map(this::response).toList();}
 private OrderResponse response(CustomerOrder order){return new OrderResponse(order.getId(),order.getStatus().name(),order.getTotal(),order.getCreatedAt(),order.getItems().stream().map(item->new OrderResponse.Item(item.getProduct().getId(),item.getProductName(),item.getUnitPrice(),item.getQuantity(),item.getSubtotal())).toList());}}
